/**
 * What the assistant looked up to produce an answer.
 *
 * WHY THIS IS SHOWN AT ALL. The answer is generated by a language model reading real lead data,
 * and the single most reasonable question an owner can ask is *"where did you get that?"*. A
 * collapsed list of the tools that ran — and which were refused — is the difference between a
 * CRM feature and an oracle.
 *
 * It shows tool NAMES and outcomes, never result rows. The data belongs in the answer, where
 * the model decided it was relevant; duplicating it into a debug panel would route lead data
 * around that judgement entirely.
 */
import { useState } from 'react';

import { type AssistantStep } from '../../api/endpoints';

const TOOL_LABELS: Record<string, string> = {
  search_leads: 'Searched leads',
  get_lead_detail: 'Opened a lead',
  get_conversation_messages: 'Read the conversation',
  find_inactive_leads: 'Checked for quiet leads',
  get_pending_reminders: 'Checked your reminders',
  get_contact_detail: 'Looked up a contact',
  get_lead_intelligence: 'Analysed the lead score',
};

const label = (tool: string) => TOOL_LABELS[tool] ?? tool.replace(/_/g, ' ');

export interface AssistantStepsProps {
  steps: AssistantStep[];
  usedHistory?: boolean;
}

const AssistantSteps = ({ steps, usedHistory }: AssistantStepsProps) => {
  const [open, setOpen] = useState(false);
  const refused = steps.filter((step) => !step.ok).length;

  return (
    <div className="rounded-xl border border-slate-200 bg-slate-50/70 dark:border-slate-700 dark:bg-slate-800/40">
      <button
        type="button"
        onClick={() => setOpen((value) => !value)}
        aria-expanded={open}
        className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs font-semibold text-slate-600 transition hover:text-slate-900 dark:text-slate-400 dark:hover:text-slate-100"
      >
        <svg
          viewBox="0 0 24 24"
          aria-hidden="true"
          className={`h-3.5 w-3.5 shrink-0 transition-transform ${open ? 'rotate-90' : ''}`}
          fill="none"
          stroke="currentColor"
          strokeWidth="2.5"
        >
          <path strokeLinecap="round" strokeLinejoin="round" d="m9 5 7 7-7 7" />
        </svg>

        <span>
          {steps.length} {steps.length === 1 ? 'lookup' : 'lookups'}
        </span>

        {refused > 0 ? (
          <span className="chip border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-500/30 dark:bg-amber-500/10 dark:text-amber-300">
            {refused} refused
          </span>
        ) : null}

        {usedHistory ? (
          <span className="chip chip-fill" title="Earlier conversations were searched for context">
            history
          </span>
        ) : null}
      </button>

      {open ? (
        <ul className="space-y-1.5 border-t border-slate-200 px-3 py-2.5 dark:border-slate-700">
          {steps.map((step, index) => (
            <li key={index} className="flex items-start gap-2 text-xs">
              <span
                aria-hidden="true"
                className={`mt-1 h-1.5 w-1.5 shrink-0 rounded-full ${
                  step.ok ? 'bg-emerald-500' : 'bg-amber-500'
                }`}
              />

              <span className="min-w-0 flex-1">
                <span className="font-medium text-slate-700 dark:text-slate-200">
                  {label(step.tool)}
                </span>

                {step.ok ? (
                  step.resultSummary ? (
                    <span className="text-slate-500 dark:text-slate-400">
                      {' '}
                      — {step.resultSummary}
                    </span>
                  ) : null
                ) : (
                  /* The refusal reason, shown rather than hidden: "you do not have access to
                     this conversation" explains an incomplete answer that would otherwise look
                     like the assistant simply missing something. */
                  <span className="text-amber-700 dark:text-amber-400"> — {step.error}</span>
                )}
              </span>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
};

export default AssistantSteps;
